function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

// Canonical state for System 1: the alert's first line, at most 500 characters.
// The device, its type and the site stay in the workflow for the rules and the
// escalation; the device name never joins the state, because it acts as a prior
// (docs: decisions/system1.md, rule 6).
const msg = $json.message;
const topic = $json.topic || '';
const body = msg && typeof msg === 'object' && !Array.isArray(msg) ? msg : {};
const text = [body.alert, body.message, body.text, body.description, body.msg, msg]
  .find(v => typeof v === 'string' && v.trim()) ?? JSON.stringify(msg ?? '');
const alert = (String(text).split(/\r?\n/).map(s => s.trim()).find(Boolean) || '').slice(0, 500);
const parts = topic.split('/');

return {
  json: {
    id: uuid(),
    topic,
    // alerts/<device>/critical: the topic names the device and the severity
    device: parts.length === 3 ? parts[1] : String(body.device || ''),
    device_type: String(body.device_type || ''),
    site: String(body.site || ''),
    severity: 'critical',
    alert,
    original: msg,
  },
};

// ── SITE RULES: edit for your site ─────────────────────────────────────────
// Rules always run first. An alert a rule routes never reaches System 1, and
// e-stop, door and firmware events must be caught here: System 1 answers them
// confidently and wrongly (docs: decisions/system1.md, rule 2).
const ALERT_RULES = [
  { type: 'emergency_stop', match: /\b(e-?stop|emergency stop)/i, team: 'safety' },
  { type: 'door', match: /\bdoors?\b/i, team: 'facilities' },
  { type: 'firmware', match: /\bfirmware\b/i, team: 'it' },
];
// Devices, or device types, whose alerts always go to one team
const DEVICE_RULES = {};       // e.g. { 'gw-01': 'it' }
const DEVICE_TYPE_RULES = {};  // e.g. { gateway: 'it' }
// The team for each cause System 1 can suggest. 'unknown' has none, so it is
// never a suggestion.
const CAUSE_TEAMS = {
  thermal: 'maintenance',
  mechanical: 'maintenance',
  electrical: 'electrical',
  connectivity: 'it',
  sensor_fault: 'instrumentation',
  process: 'operations',
};
// Notified on every escalation, whoever else is
const ON_CALL = 'on-call';
// ───────────────────────────────────────────────────────────────────────────

const rule = ALERT_RULES.find(r => r.match.test($json.alert));
let team = null;
let matched = null;
if (rule) {
  [team, matched] = [rule.team, 'alert:' + rule.type];
} else if (DEVICE_RULES[$json.device]) {
  [team, matched] = [DEVICE_RULES[$json.device], 'device:' + $json.device];
} else if (DEVICE_TYPE_RULES[$json.device_type]) {
  [team, matched] = [DEVICE_TYPE_RULES[$json.device_type], 'device_type:' + $json.device_type];
}

return {
  json: {
    ...$json,
    team,
    rule: matched,
    ask_system1: !team && $json.alert.length > 0,
    asked_at: Date.now(),
    config: { cause_teams: CAUSE_TEAMS, on_call: ON_CALL },
  },
};

function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

// System 1 only suggests: its cause is used when it clears the set's threshold
// (abstain is false) and the site's table maps it to a team (docs:
// decisions/system1.md §6.5). Every answer is logged, used or not.
const alert = $('Site Rules').item.json;
const res = $json;
const cause = (res.answers || {}).cause;
const team = cause && !cause.abstain ? alert.config.cause_teams[cause.choice] : undefined;
const used = Boolean(team);
const snapshot = /\/snapshots\/([0-9a-f]{40})/.exec((res.routing || {}).repo || '');

const decision = {
  id: uuid(),
  ts: new Date().toISOString(),
  set: (res.set || {}).name,
  set_version: (res.set || {}).version,
  checkpoint: (res.routing || {}).model || '',
  revision: snapshot ? snapshot[1].slice(0, 12) : '',
  caller: 'n8n-incident-escalation',
  subject: alert.device,
  state_sha256: res.state_sha256 || '',
  latency_ms: Date.now() - alert.asked_at,
  answers: cause ? { cause: { choice: cause.choice, confidence: cause.confidence, abstain: cause.abstain } } : {},
  used,
};

return {
  json: {
    ...alert,
    likely_cause: used ? cause.choice : null,
    likely_team: used ? team : null,
    system1: { asked: true, used, decision },
  },
};

// System 1 is down, slow, unauthorised or refused the request: no suggestion,
// and the alert is escalated as if System 1 didn't exist (rule 1).
const alert = $('Site Rules').item.json;
const error = $json.error || {};
return {
  json: {
    ...alert,
    likely_cause: null,
    likely_team: null,
    system1: { asked: true, used: false, error: String(error.message || error.description || 'request failed').slice(0, 200) },
  },
};

// Every critical alert is escalated, on every path: the severity comes from the
// topic, the team from a rule or, marked as suggested, from System 1, and the
// on-call recipient is always notified.
const a = $json;
const s1 = a.system1 || { asked: false };
return {
  json: {
    id: a.id,
    ts: new Date().toISOString(),
    severity: a.severity,
    device: a.device,
    device_type: a.device_type,
    site: a.site,
    topic: a.topic,
    alert: a.alert,
    on_call: a.config.on_call,
    routed_by: a.team ? 'rule' : a.likely_team ? 'system1' : 'on_call',
    team: a.team,
    rule: a.rule,
    likely_cause: a.likely_cause ?? null,
    likely_team: a.likely_team ?? null,
    suggested: Boolean(a.likely_team),
    system1: { asked: s1.asked, used: Boolean(s1.used), ...(s1.error ? { error: s1.error } : {}) },
    original: a.original,
  },
};
